.features-grid{display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; margin-top: 3rem;}
.feature-card{padding: 2rem; background: var(--glass-bg); backdrop-filter: blur(80px) saturate(1.6); border: 1px solid var(--glass-border); border-radius: 16px; transition: 0.4s cubic-bezier(0.16, 1, 0.3, 1); cursor: none; position: relative; overflow: hidden;}
.feature-card::before{content: ""; position: absolute; top: 0px; left: 0px; right: 0px; height: 1px; background: linear-gradient(90deg, transparent, oklch(0.85 0.08 200 / 0.25), transparent);}
.feature-card:hover{transform: translateY(-6px); box-shadow: oklch(0.15 0.15 290 / 0.5) 0px 40px 100px, oklch(0.75 0.12 180 / 0.12) 0px 0px 0px 1px inset;}
.feature-icon-wrap{width: 52px; height: 52px; border-radius: 14px; display: flex; align-items: center; justify-content: center; margin-bottom: 1.5rem; font-size: 1.5rem; position: relative;}
.feature-icon-wrap::after{content: ""; position: absolute; inset: -1px; border-radius: 15px; padding: 1px; background: linear-gradient(135deg, oklch(0.75 0.12 180 / 0.4), oklch(0.65 0.2 330 / 0.2)); mask: linear-gradient(rgb(255, 255, 255) 0px, rgb(255, 255, 255) 0px) content-box exclude, linear-gradient(rgb(255, 255, 255) 0px, rgb(255, 255, 255) 0px);}
.feature-title{font-size: 1rem; font-variation-settings: "wght" 400; letter-spacing: -0.01em; margin-bottom: 0.6rem; color: var(--text-primary);}
.feature-desc{font-size: 0.8rem; color: var(--text-secondary); line-height: 1.65; font-variation-settings: "wght" 300;}
.reveal{opacity: 0; transform: translateY(30px); transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1), transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);}
.reveal-delay-1{transition-delay: 0.1s;}
.reveal-delay-2{transition-delay: 0.2s;}
.reveal-delay-3{transition-delay: 0.3s;}
@media (max-width: 900px){.features-grid{grid-template-columns: 1fr;}}

